spec.section:
# profile-identity.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/profile-identity.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "description": "Explicit principal/profile/host identity and protected state bindings. Secrets are references only.",
  "examples": [
    {
      "agent_id": "mgr-infra",
      "credential_ref": "/chd/credentials/mgr-infra",
      "gateway_id": "gw-main",
      "host_id": "host-main",
      "learned_state_policy": "hermes_owned_protected",
      "learned_state_ref": "/chd/learned-state/pf-mgr-infra",
      "policy_owner": "pr-vp-owner",
      "principal_id": "pr-manager-infra",
      "profile_id": "pf-mgr-infra",
      "role": "manager",
      "room_bindings": [
        "task-auth-14"
      ],
      "session_state_ref": "/chd/session-state/pf-mgr-infra"
    }
  ],
  "properties": {
    "agent_id": {
      "pattern": "^[a-z][a-z0-9-]*$",
      "type": "string"
    },
    "credential_ref": {
      "pattern": "^/chd/credentials/[A-Za-z0-9._/-]+$",
      "type": "string"
    },
    "gateway_id": {
      "pattern": "^gw-[a-z0-9-]+$",
      "type": "string"
    },
    "host_id": {
      "pattern": "^host-[a-z0-9-]+$",
      "type": "string"
    },
    "learned_state_policy": {
      "enum": [
        "hermes_owned_protected",
        "hermes_owned_read_only"
      ]
    },
    "learned_state_ref": {
      "pattern": "^/chd/learned-state/[A-Za-z0-9._/-]+$",
      "type": "string"
    },
    "policy_owner": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "principal_id": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "profile_id": {
      "not": {
        "const": "default"
      },
      "pattern": "^pf-[a-z0-9-]+$",
      "type": "string"
    },
    "role": {
      "enum": [
        "director",
        "manager",
        "supervisor",
        "foreman",
        "worker"
      ]
    },
    "room_bindings": {
      "items": {
        "pattern": "^(obj|task|space)-[a-z0-9-]+$",
        "type": "string"
      },
      "type": "array",
      "uniqueItems": true
    },
    "session_state_ref": {
      "pattern": "^/chd/session-state/[A-Za-z0-9._/-]+$",
      "type": "string"
    }
  },
  "required": [
    "principal_id",
    "agent_id",
    "profile_id",
    "host_id",
    "role",
    "gateway_id",
    "credential_ref",
    "session_state_ref",
    "learned_state_ref",
    "learned_state_policy",
    "policy_owner"
  ],
  "title": "CHD profile identity",
  "type": "object"
}
```
